"""Migrated Meridian CRM account validation rules."""

from __future__ import annotations


def _value(record: dict | None, key: str) -> object:
    """Return a field value, treating missing and None values as empty strings."""
    if record is None:
        return ""
    value = record.get(key, "")
    return "" if value is None else value


def _text(record: dict | None, key: str) -> str:
    return str(_value(record, key))


def _number(record: dict | None, key: str) -> float:
    """Apply legacy numeric coercion: blank/missing values compare as zero."""
    value = _value(record, key)
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image against migrated VRL rules."""
    del today  # Included for the required fixed interface; unused by these rules.

    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if len(_text(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        # ACC-002
        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        # ACC-003
        if _number(record, "ANN_REV") < 0:
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        # ACC-004
        if (
            _text(old, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(record, "CRED_LIMIT") <= 0
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if len(_text(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any validation failure has blocking severity."""
    return any(error.get("severity") == "BLOCK" for error in errors)
